import * as runtime from "@prisma/client/runtime/client";
const config = {
    "previewFeatures": [],
    "clientVersion": "7.10.0",
    "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
    "activeProvider": "postgresql",
    "inlineSchema": "// Prisma schema — anomChat (server).\n// Modelo de datos de usuario + autenticación (sesiones y refresh tokens),\n// clonado de la arquitectura de RIA (radilab) pero SIN permisos/perfiles/tenant.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// Catálogo de tipos de documento (CC, TI, CE, …). Lookup para los usuarios.\nmodel DocumentType {\n  id          String   @id @unique @default(uuid()) @db.Uuid\n  name        String   @unique @db.VarChar(100)\n  code        String   @unique @db.VarChar(20)\n  description String?  @db.Text\n  status      Boolean  @default(true)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  users User[]\n\n  @@index([name])\n  @@index([code])\n  @@map(\"anomchat_document_types\")\n}\n\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n  PENDING\n  DELETED\n}\n\n/// Usuario del sistema. Datos personales + credenciales + control de bloqueo por\n/// intentos fallidos. Nunca se expone `password`.\nmodel User {\n  id                    String     @id @unique @default(uuid()) @db.Uuid\n  email                 String     @unique @db.VarChar(255)\n  username              String     @unique @db.VarChar(50)\n  password              String\n  firstName             String     @map(\"first_name\") @db.VarChar(100)\n  secondName            String?    @map(\"second_name\") @db.VarChar(100)\n  firstLastName         String     @map(\"first_last_name\") @db.VarChar(100)\n  secondLastName        String?    @map(\"second_last_name\") @db.VarChar(100)\n  documentTypeId        String     @map(\"document_type_id\") @db.Uuid\n  documentNumber        String     @map(\"document_number\") @db.VarChar(50)\n  phoneNumber           String?    @map(\"phone_number\") @db.VarChar(20)\n  // PIN de descubrimiento: ÚNICO en el sistema, es la forma de encontrar a un\n  // usuario. El default (dbgenerated) lo autogenera en BD (8 hex en mayúscula);\n  // la app lo genera con reintento para garantizar unicidad.\n  pin                   String     @unique @default(dbgenerated(\"(upper(substr(md5((random())::text), 1, 8)))\")) @db.VarChar(16)\n  status                UserStatus @default(PENDING)\n  emailVerified         Boolean    @default(false) @map(\"email_verified\")\n  requireChangePassword Boolean    @default(false) @map(\"require_change_password\")\n  failedAttempts        Int        @default(0) @map(\"failed_attempts\")\n  lockedUntil           DateTime?  @map(\"locked_until\")\n  // Momento del bloqueo por intentos fallidos. USO INTERNO: nunca se expone.\n  blockedAt             DateTime?  @map(\"blocked_at\")\n  lastLogin             DateTime?  @map(\"last_login\")\n  createdAt             DateTime   @default(now()) @map(\"created_at\")\n  updatedAt             DateTime   @updatedAt @map(\"updated_at\")\n\n  documentType          DocumentType           @relation(fields: [documentTypeId], references: [id], onDelete: Restrict)\n  sessions              Session[]\n  refreshTokens         RefreshToken[]\n  blackListAccessTokens BlackListAccessToken[]\n  avatars               UserAvatar[]\n  conversationsAsA      Conversation[]         @relation(\"ConversationUserA\")\n  conversationsAsB      Conversation[]         @relation(\"ConversationUserB\")\n  sentMessages          Message[]              @relation(\"MessageSender\")\n\n  @@index([email])\n  @@index([username])\n  @@index([status])\n  @@index([documentTypeId])\n  @@index([pin])\n  @@map(\"anomchat_users\")\n}\n\n/// Sesión activa (una por access token vigente). `jti` guarda el identificador\n/// único (JTI) del access token; `sessionKey` ata la sesión a su cadena de refresh.\nmodel Session {\n  id         String   @id @unique @default(uuid()) @db.Uuid\n  userId     String   @map(\"user_id\") @db.Uuid\n  jti        String   @unique @db.Uuid\n  sessionKey String   @map(\"session_key\") @db.Uuid\n  ipAddress  String?  @map(\"ip_address\") @db.VarChar(45)\n  userAgent  String?  @map(\"user_agent\")\n  isActive   Boolean  @default(true) @map(\"is_active\")\n  expiresAt  DateTime @map(\"expires_at\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([jti])\n  @@index([expiresAt])\n  @@map(\"anomchat_sessions\")\n}\n\n/// Refresh token (rotado en cada refresh). `jti` guarda el identificador único\n/// (JTI) del refresh JWT. `isRevoked` marca la revocación persistida.\nmodel RefreshToken {\n  id         String   @id @unique @default(uuid()) @db.Uuid\n  userId     String   @map(\"user_id\") @db.Uuid\n  sessionKey String   @map(\"session_key\") @db.Uuid\n  jti        String   @db.Uuid\n  isRevoked  Boolean  @default(false) @map(\"is_revoked\")\n  expiresAt  DateTime @map(\"expires_at\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, jti])\n  @@index([userId])\n  @@index([jti])\n  @@index([expiresAt])\n  @@map(\"anomchat_refresh_tokens\")\n}\n\nenum AvatarType {\n  THUMBNAIL\n  ORIGINAL\n}\n\n/// Foto de perfil del usuario. Dos filas por usuario como máximo (una por tipo):\n/// `THUMBNAIL` (pequeña) y `ORIGINAL` (detalle, calidad similar). Ambas en webp.\nmodel UserAvatar {\n  id        String     @id @unique @default(uuid()) @db.Uuid\n  userId    String     @map(\"user_id\") @db.Uuid\n  type      AvatarType\n  /// Key del objeto en el bucket (p. ej. avatars/<userId>/<userId>-thumbnail.webp).\n  key       String     @db.VarChar(255)\n  /// URL pública del objeto.\n  url       String     @db.VarChar(500)\n  createdAt DateTime   @default(now()) @map(\"created_at\")\n  updatedAt DateTime   @updatedAt @map(\"updated_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, type])\n  @@index([userId])\n  @@map(\"anomchat_user_avatars\")\n}\n\n/// Blacklist de access tokens revocados (por JTI). Defensa en profundidad para\n/// invalidar de inmediato un access token aún no expirado (logout, rotación,\n/// bloqueo). La validación rápida en cada request la hace Redis; esta tabla es\n/// el respaldo persistente.\nmodel BlackListAccessToken {\n  id        String   @id @unique @default(uuid()) @db.Uuid\n  userId    String   @map(\"user_id\") @db.Uuid\n  jti       String   @db.Uuid\n  expiresAt DateTime @map(\"expires_at\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, jti])\n  @@index([userId])\n  @@index([jti])\n  @@map(\"anomchat_blacklist_access_tokens\")\n}\n\n/// Conversación entre DOS usuarios (tabla intermedia — hace el rol de \"chat\").\n/// Cada participante tiene un alias asignado por el sistema (nombres tipo animal,\n/// sin relación con el usuario) y su propio flag de modo anónimo: si `anonymousX`\n/// es true, la contraparte lo ve por su alias; si es false, ve su identidad real.\n/// La app debe canonicalizar el par (userA = id menor) para evitar duplicados A/B.\nmodel Conversation {\n  id            String    @id @unique @default(uuid()) @db.Uuid\n  userAId       String    @map(\"user_a_id\") @db.Uuid\n  userBId       String    @map(\"user_b_id\") @db.Uuid\n  aliasA        String    @map(\"alias_a\") @db.VarChar(60)\n  aliasB        String    @map(\"alias_b\") @db.VarChar(60)\n  anonymousA    Boolean   @default(true) @map(\"anonymous_a\")\n  anonymousB    Boolean   @default(true) @map(\"anonymous_b\")\n  lastMessageAt DateTime? @map(\"last_message_at\")\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\")\n\n  userA    User      @relation(\"ConversationUserA\", fields: [userAId], references: [id], onDelete: Cascade)\n  userB    User      @relation(\"ConversationUserB\", fields: [userBId], references: [id], onDelete: Cascade)\n  messages Message[]\n\n  @@unique([userAId, userBId])\n  @@index([userAId])\n  @@index([userBId])\n  @@index([lastMessageAt])\n  @@map(\"anomchat_conversations\")\n}\n\n/// Contenido del chat: cada mensaje enviado dentro de una conversación.\n/// `readAt` marca la confirmación de lectura (check amarillo cuando != null).\n/// `replyToId` permite que un mensaje responda a otro de la misma conversación.\nmodel Message {\n  id             String    @id @unique @default(uuid()) @db.Uuid\n  conversationId String    @map(\"conversation_id\") @db.Uuid\n  senderId       String    @map(\"sender_id\") @db.Uuid\n  content        String    @db.Text\n  readAt         DateTime? @map(\"read_at\")\n  replyToId      String?   @map(\"reply_to_id\") @db.Uuid\n  createdAt      DateTime  @default(now()) @map(\"created_at\")\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  sender       User         @relation(\"MessageSender\", fields: [senderId], references: [id], onDelete: Cascade)\n  // Mensaje al que responde (si el original se borra, la respuesta queda sin cita).\n  replyTo      Message?     @relation(\"MessageReplies\", fields: [replyToId], references: [id], onDelete: SetNull)\n  replies      Message[]    @relation(\"MessageReplies\")\n\n  @@index([conversationId])\n  @@index([senderId])\n  @@index([createdAt])\n  @@index([replyToId])\n  @@map(\"anomchat_messages\")\n}\n",
    "runtimeDataModel": {
        "models": {},
        "enums": {},
        "types": {}
    },
    "parameterizationSchema": {
        "strings": [],
        "graph": ""
    }
};
